dashboard.definition:
{
    "title": "Server Infrastructure",
    "description": "Server infrastructure: VM, ESXi and Windows performance from the metrics indexes",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_vm": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_vmware_metrics metric_name IN (\"vmware.vm.cpu.usage.pct\", \"vmware.vm.memory.usage.gb\", \"vmware.vm.disk.usage.pct\") location=\"$site$\" BY metric_name vm_name location span=5m",
                "enableSmartSources": true
            },
            "name": "VM metrics (5 min)"
        },
        "ds_esxi": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_vmware_metrics metric_name IN (\"vmware.esxi.cpu.usage.pct\", \"vmware.esxi.memory.usage.pct\", \"vmware.esxi.network.rx.mbps\", \"vmware.esxi.network.tx.mbps\") location=\"$site$\" BY metric_name host location span=5m",
                "enableSmartSources": true
            },
            "name": "ESXi metrics (5 min)"
        },
        "ds_win": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_windows_metrics metric_name IN (\"windows.cpu.usage.pct\", \"windows.memory.usage.pct\", \"windows.disk.usage.pct\", \"windows.disk.queue.length\") location=\"$site$\" BY metric_name server location span=5m",
                "enableSmartSources": true
            },
            "name": "Windows metrics (5 min)"
        },
        "ds_k_vmcpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_vm",
                "query": "| where metric_name=\"vmware.vm.cpu.usage.pct\" | timechart span=5m avg(value) as \"VM CPU\""
            }
        },
        "ds_k_vms": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_vm",
                "query": "| stats dc(vm_name) as VMs"
            }
        },
        "ds_k_esxcpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_esxi",
                "query": "| where metric_name=\"vmware.esxi.cpu.usage.pct\" | timechart span=5m avg(value) as \"ESXi CPU\""
            }
        },
        "ds_k_hosts": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_esxi",
                "query": "| stats dc(host) as Hosts"
            }
        },
        "ds_k_wincpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_win",
                "query": "| where metric_name=\"windows.cpu.usage.pct\" | timechart span=5m avg(value) as \"Windows CPU\""
            }
        },
        "ds_k_winmem": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_win",
                "query": "| where metric_name=\"windows.memory.usage.pct\" | timechart span=5m avg(value) as \"Windows memory\""
            }
        },
        "ds_heat_vm": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_vm",
                "query": "| where metric_name=\"vmware.vm.cpu.usage.pct\" | timechart span=5m limit=0 avg(value) by vm_name"
            }
        },
        "ds_rings_esxi": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_esxi",
                "query": "| where metric_name=\"vmware.esxi.cpu.usage.pct\"\n| stats avg(value) as value by host\n| eval name=host, value=round(value, 1), unit=\"%\", warn=70, crit=85, better=\"lower\"\n| table name value unit warn crit better"
            }
        },
        "ds_esxi_net": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_esxi",
                "query": "| where like(metric_name, \"vmware.esxi.network.%\")\n| eval series=host.\" \".if(like(metric_name, \"%.rx.mbps\"), \"RX\", \"TX\")\n| timechart span=5m limit=0 avg(value) by series"
            }
        },
        "ds_heat_win": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_win",
                "query": "| where metric_name=\"windows.cpu.usage.pct\" | timechart span=5m limit=0 avg(value) by server"
            }
        },
        "ds_vm_mem": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_vm",
                "query": "| where metric_name=\"vmware.vm.memory.usage.gb\" | timechart span=5m limit=0 avg(value) by vm_name"
            }
        },
        "ds_vm_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_vm",
                "query": "| stats latest(value) as value by vm_name location metric_name\n| eval metric=case(metric_name=\"vmware.vm.cpu.usage.pct\", \"CPU %\", metric_name=\"vmware.vm.memory.usage.gb\", \"Memory GB\", true(), \"Disk %\")\n| eval value=round(value, 1)\n| chart first(value) over vm_name by metric\n| rename vm_name as \"VM\""
            }
        },
        "ds_esxi_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_esxi",
                "query": "| stats latest(value) as value by host location metric_name\n| eval metric=case(metric_name=\"vmware.esxi.cpu.usage.pct\", \"CPU %\", metric_name=\"vmware.esxi.memory.usage.pct\", \"Memory %\", metric_name=\"vmware.esxi.network.rx.mbps\", \"RX Mbps\", true(), \"TX Mbps\")\n| eval value=round(value, 1)\n| chart first(value) over host by metric\n| rename host as \"ESXi host\""
            }
        },
        "ds_win_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_win",
                "query": "| stats latest(value) as value by server location metric_name\n| eval metric=case(metric_name=\"windows.cpu.usage.pct\", \"CPU %\", metric_name=\"windows.memory.usage.pct\", \"Memory %\", metric_name=\"windows.disk.usage.pct\", \"Disk %\", true(), \"Disk queue\")\n| eval value=round(value, 1)\n| chart first(value) over server by metric\n| rename server as \"Windows server\""
            }
        },
        "ds_win_events": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_windows_events location=\"$site$\"\n| stats count as Count dc(ComputerName) as Hosts latest(_time) as last latest(Message) as Message by EventType EventCode SourceName\n| eval prio=case(EventType=\"Error\", 0, EventType=\"Warning\", 1, true(), 2), Message=replace(Message, \"(?s)[\\r\\n].*\", \"\"), Time=strftime(last, \"%H:%M:%S\")\n| sort prio - Count\n| head 20\n| table Time EventType EventCode SourceName Hosts Count Message\n| rename EventType as Type EventCode as \"Event code\" SourceName as Source",
                "enableSmartSources": true
            },
            "name": "Windows events"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_exec.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_executive",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_factory": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_factory.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
