        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_vmcpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 85,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_vms"
            },
            "options": {
                "majorColor": "#2dd4bf",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_esxcpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 85,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_hosts"
            },
            "options": {
                "majorColor": "#2dd4bf",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_wincpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 85,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_winmem"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 80,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 80,
                        "to": 90,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 90,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_vm"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 70,
                "crit": 85,
                "unit": "%",
                "maxSeries": 40
            }
        },
        "viz_08": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_vm_mem"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "lineWidth": 2
            }
        },
        "viz_09": {
            "type": "coolashaker_studio.health_rings",
            "dataSources": {
                "primary": "ds_rings_esxi"
            },
            "options": {
                "decimals": 1
            }
        },
        "viz_10": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_esxi_net"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "lineWidth": 2
            }
        },
        "viz_11": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_win"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 70,
                "crit": 85,
                "unit": "%"
            }
        },
        "viz_12": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_win_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 8,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "CPU %": {
                        "rowBackgroundColors": "> table | seriesByName(\"CPU %\") | rangeValue(range_2)"
                    },
                    "Memory %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Memory %\") | rangeValue(range_3)"
                    },
                    "Disk %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Disk %\") | rangeValue(range_4)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ],
                "range_2": [
                    {
                        "to": 70,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 85,
                        "value": "#5a1426"
                    }
                ],
                "range_3": [
                    {
                        "to": 80,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 80,
                        "to": 90,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 90,
                        "value": "#5a1426"
                    }
                ],
                "range_4": [
                    {
                        "to": 80,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 80,
                        "to": 90,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 90,
                        "value": "#5a1426"
                    }
                ]
            }
        },
        "viz_13": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_vm_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 9,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "CPU %": {
                        "rowBackgroundColors": "> table | seriesByName(\"CPU %\") | rangeValue(range_2)"
                    },
                    "Disk %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Disk %\") | rangeValue(range_3)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
